insert into public.companies (slug, name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar, logo_url, cover_url, brand_color, phone, email, website, established_year, sort_order) values ('nova-pharma', 'Nova Pharma', 'نوفا فارما', 'Everyday medicines you can trust', 'أدوية يومية موثوقة', 'Nova Pharma supplies essential over-the-counter and prescription medicines across the UAE, sourced and stored through Sharjah Drug Store under strict quality and cold-chain standards.', 'توفر نوفا فارما الأدوية الأساسية والأدوية الموصوفة في جميع أنحاء الإمارات، ويتم توريدها وتخزينها عبر مستودع الشارقة للأدوية وفق أعلى معايير الجودة وسلسلة التبريد.', '/seed/companies/nova-pharma-logo.webp', '/seed/companies/nova-pharma-cover.webp', '#1D5FA8', '+971 6 530 1000', 'info@nova-pharma.ae', null, 2006, 0);
insert into public.companies (slug, name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar, logo_url, cover_url, brand_color, phone, email, website, established_year, sort_order) values ('medilife-labs', 'MediLife Labs', 'ميديلايف لابز', 'Science-backed vitamins & supplements', 'فيتامينات ومكملات مدعومة علميًا', 'MediLife Labs focuses on high-quality vitamins, minerals and daily supplements formulated to support immunity, energy and long-term wellness for the whole family.', 'تركز ميديلايف لابز على الفيتامينات والمعادن والمكملات اليومية عالية الجودة، المصممة لدعم المناعة والطاقة والصحة على المدى الطويل لجميع أفراد العائلة.', '/seed/companies/medilife-labs-logo.webp', '/seed/companies/medilife-labs-cover.webp', '#0E8A7E', '+971 6 531 1100', 'info@medilife-labs.ae', null, 2010, 1);
insert into public.companies (slug, name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar, logo_url, cover_url, brand_color, phone, email, website, established_year, sort_order) values ('zayna-care', 'Zayna Care', 'زينة كير', 'Gentle care for skin, baby & family', 'عناية لطيفة بالبشرة والطفل والعائلة', 'Zayna Care develops dermatologically tested personal care and baby care products, made gentle enough for sensitive skin and everyday family use.', 'تطور زينة كير منتجات عناية شخصية وعناية بالطفل مختبرة جلديًا، لطيفة بما يكفي للبشرة الحساسة والاستخدام العائلي اليومي.', '/seed/companies/zayna-care-logo.webp', '/seed/companies/zayna-care-cover.webp', '#B83268', '+971 6 532 1200', 'info@zayna-care.ae', null, 2013, 2);
insert into public.companies (slug, name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar, logo_url, cover_url, brand_color, phone, email, website, established_year, sort_order) values ('crescent-health', 'Crescent Health', 'كريسنت هيلث', 'Diabetes care & home health devices', 'رعاية السكري والأجهزة الصحية المنزلية', 'Crescent Health provides reliable diabetes care supplies, home monitoring devices and first aid essentials for pharmacies, clinics and households.', 'توفر كريسنت هيلث مستلزمات رعاية السكري وأجهزة المراقبة المنزلية ومستلزمات الإسعافات الأولية بموثوقية عالية للصيدليات والعيادات والمنازل.', '/seed/companies/crescent-health-logo.webp', '/seed/companies/crescent-health-cover.webp', '#D0661C', '+971 6 533 1300', 'info@crescent-health.ae', null, 2009, 3);
insert into public.companies (slug, name_en, name_ar, tagline_en, tagline_ar, description_en, description_ar, logo_url, cover_url, brand_color, phone, email, website, established_year, sort_order) values ('oasis-herbals', 'Oasis Herbals', 'واحة الأعشاب', 'Natural remedies, rooted in tradition', 'علاجات طبيعية بجذور تقليدية', 'Oasis Herbals brings together traditional herbal remedies and modern nutrition — from black seed oil and Sidr honey to standardized herbal extracts.', 'تجمع واحة الأعشاب بين العلاجات العشبية التقليدية والتغذية الحديثة، من زيت الحبة السوداء وعسل السدر إلى المستخلصات العشبية المعيارية.', '/seed/companies/oasis-herbals-logo.webp', '/seed/companies/oasis-herbals-cover.webp', '#4F7F24', '+971 6 534 1400', 'info@oasis-herbals.ae', null, 2015, 4);
